import json

def get_config_from_text(input_str):
    try:
        config_data = json.loads(input_str)
    except json.JSONDecodeError:
        raise ValueError

    if not isinstance(config_data, dict):
        raise ValueError

    if 'retry_count' not in config_data:
        config_data['retry_count'] = 3

    return config_data
